#include <vector>

using namespace std;

class Solution {
public:
    int minKBitFlips(vector<int>& nums, int k) {
        int n = nums.size(), flips = 0, flipped = 0;
        vector<int> isFlipped(n, 0);

        for (int i = 0; i < n; ++i) {
            if (i >= k) flipped ^= isFlipped[i - k];
            if ((nums[i] ^ flipped) == 0) {
                if (i + k > n) return -1;
                isFlipped[i] = 1;
                flipped ^= 1;
                flips++;
            }
        }
        return flips;
    }
};
